import java.net.URL;
import java.net.URISyntaxException;

public class ClassX {
    /**
     * Mengambil konten dari URL yang dihasilkan setelah memvalidasi host.
     * 
     * Fungsi ini membersihkan host dengan memeriksa karakter tidak valid seperti spasi.
     */
    public static String getContentFromURL(String urlString) throws URISyntaxException {
        // Validasi URL
        URL url = new URL(urlString);

        // Membersihkan host dari karakter tidak valid
        String host = url.getHost().replace(" ", "");

        // Membuat URL baru dengan host yang telah diperbarui
        URL updatedUrl = new URL(url.getProtocol(), host, url.getPort(), url.getFile());

        // Mengambil konten dari URL baru
        try (java.io.InputStream inputStream = updatedUrl.openStream()) {
            java.util.Scanner scanner = new java.util.Scanner(inputStream);
            StringBuilder content = new StringBuilder();
            while (scanner.hasNextLine()) {
                content.append(scanner.nextLine()).append("\n");
            }
            scanner.close();
            return content.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error fetching content from URL: " + urlString, e);
        }
    }
