    private Map<String, String> parseHeader(String header) {
        // Decode base64 header
        byte[] decodedHeader = Base64.getDecoder().decode(header);

        // Convert decoded bytes to a string
        String headerString = new String(decodedHeader);

        // Split header string into key-value pairs
        Map<String, String> headerMap = new HashMap<>();
        String[] keyValuePairs = headerString.split(",");

        for (String pair : keyValuePairs) {
            String[] keyValue = pair.split(":");
            headerMap.put(keyValue[0].trim(), keyValue[1].trim());
        }

        return headerMap;
    }
