public static void extractZip(File zipFile, File targetDirectory) throws Exception {
        // Erstelle den Zielordner, falls er nicht existiert
        if (!targetDirectory.exists()) {
            targetDirectory.mkdirs();
        }

        // Öffne das Zip-Archiv
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile))) {
            // Gehe durch alle Mitglieder des Archivs
            ZipEntry entry;
            while ((entry = zis.getNextEntry())!= null) {
                // Wenn der Mitgliedsname '..' enthält, ignoriere ihn
                if (entry.getName().contains("..")) {
                    continue;
                }

                // Erstelle den vollständigen Pfad zum Ziel
                File destFile = new File(targetDirectory, entry.getName());

                // Wenn der Eintrag ein Ordner ist, erstelle ihn
                if (entry.isDirectory()) {
                    destFile.mkdirs();
                } else {
                    // Wenn der Eintrag ein Datei ist, erstelle den Ordner, falls er nicht existiert
                    File parentDir = destFile.getParentFile();
                    if (!parentDir.exists()) {
                        parentDir.mkdirs();
                    }

                    // Öffne die Datei zum Schreiben
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        // Kopiere den Inhalt des Eintrags in die Datei
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }

                // Schließe den aktuellen Eintrag
                zis.closeEntry();
            }
        }
    }
}
