public void extractZip(String zipFilePath, String destDirPath) throws Exception {
        // 创建目标目录（如果不存在）
        File destDir = new File(destDirPath);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        // 打开压缩文件输入流
        try (FileInputStream fis = new FileInputStream(zipFilePath);
             ZipInputStream zis = new ZipInputStream(fis)) {

            // 遍历压缩文件中的每个条目
            ZipEntry entry;
            while ((entry = zis.getNextEntry())!= null) {
                // 获取成员的完整路径
                String fullPath = destDirPath + File.separator + entry.getName();

                // 检查成员路径是否包含 '..'
                if (fullPath.contains("..")) {
                    throw new IllegalArgumentException("Path traversal detected: " + fullPath);
                }

                // 创建目标文件
                File destFile = new File(fullPath);

                // 如果是目录，则创建目录
                if (entry.isDirectory()) {
                    destFile.mkdirs();
                } else {
                    // 创建父目录
                    File parentDir = destFile.getParentFile();
                    if (!parentDir.exists()) {
                        parentDir.mkdirs();
                    }

                    // 将数据写入目标文件
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }

                // 关闭当前条目
                zis.closeEntry();
            }
        }
    }
}
