import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Extrahiert ein bestimmtes Mitglied aus einem Archiv (simuliert).
     * 
     * Die Funktion überprüft, ob der Mitgliedsname mit einem Schrägstrich beginnt, um absolute Pfade zu verhindern.
     */
    public static void extractMember(String archivePath, String memberName) {
        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(archivePath))) {
            ZipEntry entry;
            while ((entry = zipIn.getNextEntry())!= null) {
                if (!entry.isDirectory() && entry.getName().equals(memberName)) {
                    File destFile = new File("extracted_" + entry.getName());
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                    System.out.println("Extrahiert: " + destFile.getAbsolutePath());
                    break;
                }
                zipIn.closeEntry();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        String archivePath = "path/to/your/archive.zip";
        String memberName = "member/file.txt";
        extractMember(archivePath, memberName);
    }
}
