    public static void extractMember(String archivePath, String memberName) throws IOException {
        File archiveFile = new File(archivePath);
        if (!archiveFile.exists()) {
            throw new FileNotFoundException("Arşiv dosyası bulunamadı: " + archivePath);
        }

        // Arşiv dosyasının uzantısı kontrolü
        String extension = archiveFile.getName().substring(archiveFile.getName().lastIndexOf('.'));
        if (!extension.equals(".zip")) {
            throw new IllegalArgumentException("Geçersiz arşiv dosyası türü: " + extension);
        }

        // Üyeyinin adının eğik çizgi ile başlayıp başlamadığını kontrol etme
        if (!memberName.startsWith("/")) {
            memberName = "/" + memberName;
        }

        // Arşiv dosyasının içeriğini açma
        ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(archiveFile));
        ZipEntry entry;
        while ((entry = zipInputStream.getNextEntry())!= null) {
            if (entry.getName().equals(memberName)) {
                // Üyeyi çıkarma işlemi burada gerçekleşecek
                // Bu örnekte sadece dosya adını yazdıralım
                System.out.println("Üye çıkarıldı: " + entry.getName());
                break;
            }
            zipInputStream.closeEntry();
        }
        zipInputStream.close();
    }
}
