     */
    public static void extractMember(File archive, String memberName) throws IOException {
        // Arşiv dosyasının yolunu oluştur
        Path archivePath = Paths.get(archive.getAbsolutePath());

        // Üyeyin yolunu oluştur
        Path memberPath = Paths.get(memberName);

        // Üyeyin yolunun mutlak olması kontrol edilir
        if (!memberPath.isAbsolute()) {
            // Mutlak yolu oluştur
            memberPath = archivePath.resolveSibling(memberName);
        }

        // Üyeyi arşivden çıkar
        Files.copy(memberPath, Paths.get("extracted_" + memberName));
    }
}
