public static void extractMember(String memberName, String storagePath) {
        File storageDir = new File(storagePath);
        if (!storageDir.exists() ||!storageDir.isDirectory()) {
            System.out.println("Kho lưu trữ không tồn tại hoặc không phải là thư mục.");
            return;
        }

        if (memberName.startsWith("/")) {
            System.out.println("Tên thành viên không hợp lệ: không được bắt đầu bằng dấu gạch chéo.");
            return;
        }

        File memberFile = new File(storageDir, memberName);
        if (!memberFile.exists()) {
            System.out.println("Thành viên không tồn tại trong kho lưu trữ.");
            return;
        }

        // Đọc nội dung thành viên từ file
        try {
            String content = readFile(memberFile);
            System.out.println("Nội dung thành viên: " + content);
        } catch (Exception e) {
            System.err.println("Lỗi khi đọc nội dung thành viên: " + e.getMessage());
        }
    }

    private static String readFile(File file) throws Exception {
        StringBuilder content = new StringBuilder();
        try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
            String line;
            while ((line = reader.readLine())!= null) {
                content.append(line).append("\n");
            }
        }
        return content.toString().trim();
    }
}
