public class ClassX {
    /**
     * מוציא חבר ספציפי מארכיון (מדמה).
     * 
     * הפונקציה בודקת אם שם החבר מתחיל בסלש כדי למנוע מסלולים מוחלטים.
     * @param fileName The name of the file containing the list of friends.
     * @param friendName The name of the friend to remove.
     * @return true if the friend was successfully removed, false otherwise.
     * @throws IOException If an I/O error occurs while reading or writing the file.
     */
    public boolean removeFriend(String fileName, String friendName) throws IOException {
        File file = new File(fileName);
        if (!file.exists()) {
