            while ((line = errorReader.readLine())!= null) {
                System.err.println(line);
            }

            // 等待命令完成
            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
