    private static String buildCommand(String mimeType, String fileName) {
        // Contoh pembuatan perintah
        StringBuilder commandBuilder = new StringBuilder();

        // Cek jika MIME type dan file name tidak kosong
        if (mimeType!= null &&!mimeType.isEmpty() && fileName!= null &&!fileName.isEmpty()) {
            // Menambahkan perintah untuk melihat file berdasarkan MIME type
            commandBuilder.append("file -i ").append(fileName);

            // Cek jika hasil dari perintah tersebut mengandung MIME type yang sesuai
            String result = executeCommand(commandBuilder.toString());
            if (result!= null && result.contains(mimeType)) {
                return "open " + fileName;
            }
        }

        return null;
    }

    private static String executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            StringBuilder output = new StringBuilder();
            String line;
            while ((line = reader.readLine())!= null) {
                output.append(line).append("\n");
            }
            process.waitFor();
            return output.toString();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
