public static void main(String[] args) {
        String mimeType = "text/plain"; // Beispiel MIME-Type
        String filePath = "/path/to/file.txt"; // Beispiel Pfad zur Datei

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String command = constructCommand(mimeType, filePath);
            executeCommand(command);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String constructCommand(String mimeType, String filePath) {
        StringBuilder commandBuilder = new StringBuilder();

        // Check if the mimeType contains semicolons to prevent command injection
        if (mimeType.contains(";")) {
            throw new IllegalArgumentException("MIME type contains semicolons, which can lead to command injection.");
        }

        // Construct the command to display the file based on the MIME type
        commandBuilder.append("xdg-open ").append(filePath).append(" &");

        return commandBuilder.toString();
    }

    private static void executeCommand(String command) throws Exception {
        // Execute the command using Runtime.getRuntime().exec()
        Process process = Runtime.getRuntime().exec(command);
        int exitCode = process.waitFor();

        if (exitCode!= 0) {
            throw new RuntimeException("Command execution failed with exit code: " + exitCode);
        }
    }
}
