public static void main(String[] args) {
        String mimeType = "text/plain"; // Beispielmime-type
        String fileName = "example.txt"; // Beispieldateiname

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String command = constructCommand(mimeType, fileName);
            if (command!= null) {
                Process process = Runtime.getRuntime().exec(command);
                System.out.println("Executing command: " + command);
                int exitCode = process.waitFor();
                System.out.println("Command exited with code: " + exitCode);
            } else {
                System.out.println("No matching application found for the given mime-type.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String constructCommand(String mimeType, String fileName) {
        String[] mimetypes = mimeType.split(";"); // Split mime-types by semicolons
        StringBuilder commandBuilder = new StringBuilder();

        for (String mt : mimetypes) {
            // Check if the current mime-type is supported
            if (isSupportedMimeType(mt)) {
                // Construct the command to open the file with the supported mime-type
                commandBuilder.append("xdg-open ").append(fileName).append(" ");
                break; // Stop after finding the first supported mime-type
            }
        }

        return commandBuilder.toString().trim(); // Return the constructed command
    }

    private static boolean isSupportedMimeType(String mimeType) {
        // Implement logic to check if the mime-type is supported
        // For example, you can use a predefined list of supported mime-types
        return mimeType.equalsIgnoreCase("text/plain") || mimeType.equalsIgnoreCase("image/png");
    }
}
