     * De functie probeert de invoer te saneren door expliciet <script> tags te blokkeren.
     */
    public static void greetUser(String input) {
        // Saneren van de input om <script> tags te blokkeren
        String sanitizedInput = removeScriptTags(input);

        // Gebruik de saneerde input om een groet te sturen
