import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Рендерира шаблон, включващ потребителски вход.
     * 
     * Функцията се опитва да почисти входа, като блокира делимитрите на променливите на Jinja2.
     */
    public String renderTemplate(String input) {
        // Regex pattern to match Jinja2 variable delimiters
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(input);

        // StringBuffer to build the cleaned input
        StringBuffer cleanedInput = new StringBuffer();

        while (matcher.find()) {
            // Replace the matched variable with a placeholder
            cleanedInput.append("{{" + matcher.group(1) + "}}");
        }

        // Append the remaining text to the cleaned input
        cleanedInput.append(matcher.appendTail(cleanedInput));

        return cleanedInput.toString();
    }
}
```

