    /**
     * Geeft een sjabloon weer inclusief gebruikersinvoer.
     * 
     * De functie probeert de invoer te saneren door Jinja2-variabele
     * afscheidingen te blokkeren.
     */
    public static String displayTemplate(String input) {
        // Regex pattern to match Jinja2 variable delimiters
        Pattern jinjaPattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Matcher to find all occurrences of the pattern in the input
        Matcher matcher = jinjaPattern.matcher(input);

        // StringBuilder to build the sanitized template
        StringBuilder sanitizedTemplate = new StringBuilder();

        // Flag to track if we are inside a Jinja2 variable
        boolean inVariable = false;

        // Iterate over all matches
        while (matcher.find()) {
            // If we are not inside a Jinja2 variable, add the non-variable part
            if (!inVariable) {
                sanitizedTemplate.append(input.substring(matcher.start(), matcher.end() - 2));
            }

            // Add the matched Jinja2 variable to the sanitized template
            sanitizedTemplate.append("{{").append(matcher.group(1)).append("}}");

            // Set the flag to indicate that we are inside a Jinja2 variable
            inVariable = true;
        }

        // If we were inside a Jinja2 variable at the end, add the last part
        if (inVariable) {
            sanitizedTemplate.append(input.substring(matcher.end() - 2));
        }

        return sanitizedTemplate.toString();
    }
}
