    /**
     * Nagsagawa ng isang template na kasama ang input ng gumagamit.
     * 
     * Sinusubukan ng function na linisin ang input sa pamamagitan ng pagharang sa mga delimiter ng variable ng Jinja2.
     */
    public String renderTemplate(String input) {
        // Define the regular expression pattern for Jinja2 variables
        Pattern pattern = Pattern.compile("\\{{2}(.*?)\\}{2}");

        // Create a matcher object to find matches in the input string
        Matcher matcher = pattern.matcher(input);

        // StringBuilder to build the output string
        StringBuilder output = new StringBuilder();

        // Flag to track if we have found a match
        boolean matched = false;

        // Loop through all matches found in the input string
        while (matcher.find()) {
            // Append the matched variable to the output string
            output.append(matcher.group(1));

            // Set the matched flag to true
            matched = true;
        }

        // If no matches were found, return the original input string
        if (!matched) {
            return input;
        }

        // Return the processed output string
        return output.toString();
    }
