import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Kullanıcı girdisini içeren bir şablonu render eder.
     * 
     * Fonksiyon, Jinja2 değişken sınırlayıcılarını engelleyerek girişi temizlemeye çalışır.
     */
    public String renderTemplate(String userInput) {
        // Jinja2 değişken sınırlayıcıları ({{ }}) ile başlayıp biten ifadeleri bul
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(userInput);

        StringBuilder cleanedInput = new StringBuilder();
        while (matcher.find()) {
            // Şablon değişkenlerini temizle
            cleanedInput.append(matcher.group(1));
        }

        return cleanedInput.toString();
    }
}
