        StringBuilder sanitizedInput = new StringBuilder();

        // Find all matches and replace them with an empty string
        while (matcher.find()) {
            matcher.appendReplacement(sanitizedInput, "");
        }

        // Append the remaining part of the string
        matcher.appendTail(sanitizedInput);

        return sanitizedInput.toString();
