import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Menghasilkan sebuah template yang mencakup input pengguna.
     * 
     * Fungsi ini berusaha untuk membersihkan input dengan memblokir pembatas variabel Jinja2.
     */
    public static String generateTemplate(String userInput) {
        // Pattern untuk pencarian pembatas variabel Jinja2
        Pattern jinjaPattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Matcher untuk pencarian
        Matcher matcher = jinjaPattern.matcher(userInput);

        // Membuat StringBuilder untuk menyimpan hasil
        StringBuilder cleanedInput = new StringBuilder();

        // Menambahkan karakter sebelum dan sesudah pembatas Jinja2
        while (matcher.find()) {
            cleanedInput.append(matcher.group(0));
            cleanedInput.append("{{}}");
        }

        // Menambahkan karakter setelah pembatas Jinja2
        if (matcher.hitEnd()) {
            cleanedInput.append(matcher.group());
        }

        return cleanedInput.toString();
    }
}
