import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Rinde una plantilla que incluye la entrada del usuario.
     * 
     * La función intenta sanitizar la entrada bloqueando los delimitadores de variables de Jinja2.
     */
    public String renderTemplate(String userInput) {
        // Definir un patrón para encontrar los delimitadores de variables de Jinja2
        Pattern pattern = Pattern.compile("\\{(.*?)\\}");
        Matcher matcher = pattern.matcher(userInput);

        // Crear una cadena de salida para el resultado sanitizado
        StringBuilder sanitizedOutput = new StringBuilder();

        // Iterar sobre todos los matches encontrados
        while (matcher.find()) {
            // Obtener el contenido del delimitador de variables
            String variable = matcher.group(1);
            // Añadir el contenido sanitizado a la salida
            sanitizedOutput.append(variable);
        }

        // Devolver la cadena sanitizada
        return sanitizedOutput.toString();
    }
}
