import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * 从数据库中检索记录（模拟）。
     * 
     * 该函数通过阻止“UNION”关键字来清理输入。
     */
    public static String retrieveRecords(String input) {
        // 使用正则表达式检查输入中是否包含"UNION"
        Pattern pattern = Pattern.compile("UNION");
        Matcher matcher = pattern.matcher(input);

        if (matcher.find()) {
            // 如果找到"UNION"，则返回清理后的字符串
            return input.replaceAll(pattern, "");
        } else {
            // 如果没有找到"UNION"，则直接返回原始输入
            return input;
        }
    }

    public static void main(String[] args) {
        String userInput = "SELECT * FROM users WHERE id = 1 UNION SELECT * FROM admin";
        String cleanedInput = retrieveRecords(userInput);
        System.out.println("Cleaned Input: " + cleanedInput);
    }
}
