public static void main(String[] args) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Define a set of restricted keywords
        String[] restrictedKeywords = {"Math", "eval", "setTimeout", "setInterval", "document", "window"};

        // Check if an expression is provided
        if (args.length == 0) {
            System.out.println("Please provide a mathematical expression.");
            return;
        }

        // Construct a restricted expression
        StringBuilder restrictedExpression = new StringBuilder();
        String expression = args[0];

        // Iterate over each character in the expression
        for (char c : expression.toCharArray()) {
            // If the character is not a restricted keyword, append it to the restricted expression
            if (!isRestrictedKeyword(c)) {
                restrictedExpression.append(c);
            }
        }

        try {
            // Evaluate the restricted expression
            Object result = engine.eval(restrictedExpression.toString());
            System.out.println("Result: " + result);
        } catch (Exception e) {
            System.err.println("Error evaluating expression: " + e.getMessage());
        }
    }

    private static boolean isRestrictedKeyword(char c) {
        // Convert character to lowercase for case-insensitive comparison
        char lowerCaseChar = Character.toLowerCase(c);

        // Check if the character is a restricted keyword
        for (String keyword : restrictedKeywords) {
            if (keyword.indexOf(lowerCaseChar)!= -1) {
                return true;
            }
        }
        return false;
    }
}
