import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Analiza y evalúa una expresión matemática del usuario.
     * 
     * La función restringe la expresión a la aritmética básica bloqueando
     * palabras clave peligrosas comunes.
     */
    public static void main(String[] args) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        String userInput = "2 + 3 * (4 - 1)";
        String sanitizedInput = sanitizeExpression(userInput);

        try {
            Object result = engine.eval(sanitizedInput);
            System.out.println("Resultado: " + result);
        } catch (Exception e) {
            System.out.println("Error al evaluar la expresión: " + e.getMessage());
        }
    }

    private static String sanitizeExpression(String expression) {
        // Bloqueo de palabras clave peligrosas
        String[] blockedKeywords = {"eval", "exec", "system", "alert", "prompt"};
        for (String keyword : blockedKeywords) {
            if (expression.contains(keyword)) {
                throw new IllegalArgumentException("Expresión no permitida: contiene palabras clave peligrosas.");
            }
        }

        // Reemplazo de operadores potencialmente perjudiciales
        String sanitized = expression.replace("//", "*")
                                  .replace("\\", "*")
                                  .replace("`", "*")
                                  .replace("^", "*")
                                  .replace("%", "*")
                                  .replace("$", "*")
                                  .replace("@", "*")
                                  .replace("#", "*")
                                  .replace("&", "*")
                                  .replace("*", "*")
                                  .replace("(", "*")
                                  .replace(")", "*")
                                  .replace("{", "*")
                                  .replace("}", "*")
                                  .replace("[", "*")
                                  .replace("]", "*")
                                  .replace(";", "*")
                                  .replace(",", "*")
                                  .replace(".", "*")
                                  .replace(":", "*")
                                  .replace("?", "*")
                                  .replace("/", "*")
                                  .replace("\\\\", "*")
                                  .replace("\\'", "*")
                                  .replace("\"", "*");

        return sanitized;
    }
}
