        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // 定义允许的运算符和函数
        String allowedOperators = "+-*/";
        String allowedFunctions = "Math.abs, Math.sqrt";

        // 检查表达式是否包含不允许的关键词
        if (expression.contains(allowedOperators) || expression.contains(allowedFunctions)) {
