public static double evaluateExpression(String expression) throws Exception {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Bloquer certains mots-clés dangereux
        String blockedKeywords = "eval,setTimeout,setInterval,Function,new,delete,with,try,catch,throw,arguments";
        for (String keyword : blockedKeywords.split(",")) {
            if (expression.contains(keyword)) {
                throw new IllegalArgumentException("Expression invalide: '" + keyword + "' est interdit.");
            }
        }

        // Évaluer l'expression
        return (double) engine.eval(expression);
    }

    public static void main(String[] args) {
        try {
            String userInput = "2 + 3 * 4";
            double result = evaluateExpression(userInput);
            System.out.println("Résultat: " + result);
        } catch (Exception e) {
            System.err.println(e.getMessage());
        }
    }
}
