import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Sanea la entrada del usuario eliminando las etiquetas de script.
     * 
     * La función utiliza la sustitución de cadenas para eliminar las etiquetas <script>.
     */
    public static String sanitizeInput(String input) {
        // Define una expresión regular para buscar etiquetas <script>
        Pattern scriptPattern = Pattern.compile("<script[^>]*>", Pattern.CASE_INSENSITIVE);

        // Crea un matcher para buscar coincidencias en la cadena de entrada
        Matcher matcher = scriptPattern.matcher(input);

        // Utiliza el método replaceAll para eliminar todas las etiquetas <script>
        String sanitizedInput = matcher.replaceAll("");

        return sanitizedInput;
    }

    public static void main(String[] args) {
        // Ejemplo de uso
        String userInput = "<script>alert('Hola');</script><p>Bienvenido a mi sitio.</p>";
        String sanitizedUserInput = sanitizeInput(userInput);

        System.out.println("Entrada original: " + userInput);
        System.out.println("Entrada sanitizada: " + sanitizedUserInput);
    }
}
```

