public static String getDebugInfo() {
        // 检查是否为生产环境
        if (isProductionEnvironment()) {
            return "Debug info suppressed due to production environment.";
        }

        // 创建 StringWriter 来捕获调试信息
        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);

        // 获取当前线程的堆栈跟踪信息
        StackTraceElement[] stackTrace = Thread.currentThread().getStackTrace();

        // 遍历堆栈跟踪信息并输出
        for (StackTraceElement element : stackTrace) {
            pw.println(element.toString());
        }

        // 关闭 PrintWriter
        pw.close();

        // 返回调试信息
        return sw.toString();
    }

    /**
     * 检查是否为生产环境。
     * 
     * 在实际应用中，这可能需要根据特定的配置或标志来实现。
     */
    private static boolean isProductionEnvironment() {
        // 这是一个示例实现，可以根据实际需求调整
        return System.getenv("ENVIRONMENT").equals("production");
    }
}
