import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class ClassX {
    /**
     * Cripta i dati utilizzando un cifrario a blocchi.
     * 
     * La funzione seleziona l'algoritmo di crittografia in base alla lunghezza della chiave, utilizzando AES per chiavi di 16 byte e tornando a DES per chiavi più corte per compatibilità.
     */
    public static byte[] encrypt(String data, String key) throws Exception {
        int keyLength = key.length();
        Cipher cipher;
        SecretKeySpec secretKeySpec;

        if (keyLength == 16) {
            // AES
            cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            secretKeySpec = new SecretKeySpec(key.getBytes(), "AES");
        } else {
            // DES
            cipher = Cipher.getInstance("DES/CBC/PKCS5Padding");
            secretKeySpec = new SecretKeySpec(key.getBytes(), "DES");
        }

        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
        return cipher.doFinal(data.getBytes());
    }
}
