        try {
            String originalData = "Hello, World!";
            String encryptionKey = "1234567890123456"; // Example key

            String encryptedData = encrypt(originalData, encryptionKey);
            System.out.println("Encrypted Data: " + encryptedData);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
