     */
public static String parseHttpHeader(String header) {
        // Regular expression to match only alphanumeric characters and spaces
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9\\s]+$");
        Matcher matcher = pattern.matcher(header);

