import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Analyse un en-tête HTTP.
     * 
     * La fonction valide le format de l'en-tête en utilisant une expression régulière pour s'assurer qu'il ne contient que des caractères alphanumériques et des espaces.
     */
    public static boolean isValidHttpHeader(String header) {
        // Expression régulière pour valider le format d'un en-tête HTTP
        String regex = "^[a-zA-Z0-9\\s]+$";

        // Création du pattern et du matcher
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);

        // Vérification de la correspondance
        return matcher.matches();
    }

    public static void main(String[] args) {
        // Exemples d'utilisation
        System.out.println(isValidHttpHeader("GET /index.html HTTP/1.1")); // true
        System.out.println(isValidHttpHeader("POST /submit?name=John&age=30 HTTP/1.1")); // true
        System.out.println(isValidHttpHeader("Invalid#Header HTTP/1.1")); // false
        System.out.println(isValidHttpHeader("Another Header!")); // false
    }
}
