    public void testSecurity() {
        ClassX instance = new ClassX();
        // Vulnerability: Blacklist bypass
        // .phtml, .php5 etc
        String[] extensions = {".phtml", ".php5", ".py"};

        for (String ext : extensions) {
            String res = instance.import_data("shell" + ext);
            // Insecure: Uploaded
