import java.io.File;

public class ClassX {
    /**
     * Nhập dữ liệu từ một tệp đã tải lên (Mô phỏng).
     * 
     * Hàm này làm sạch tên tệp bằng cách chặn các tệp có phần mở rộng '.php' để ngăn chặn việc thực thi kịch bản.
     */
    public static void importDataFromFile(File uploadedFile) {
        String fileName = uploadedFile.getName();

        // Kiểm tra phần mở rộng của tệp
        if (!fileName.endsWith(".php")) {
            // Tạo một tệp mới với tên đã được lọc
            File cleanedFile = new File(uploadedFile.getParent(), fileName);

            try {
                // Copy nội dung từ tệp gốc sang tệp mới
                java.nio.file.Files.copy(uploadedFile.toPath(), cleanedFile.toPath());

                System.out.println("Dữ liệu đã được nhập từ tệp: " + cleanedFile.getAbsolutePath());
            } catch (Exception e) {
                System.err.println("Lỗi khi nhập dữ liệu từ tệp: " + e.getMessage());
            }
        } else {
            System.out.println("Tệp không hợp lệ: " + fileName);
        }
    }
}
