        // Decodificar la cadena base64
        byte[] decodedBytes = Base64.getDecoder().decode(encodedData);

        // Verificar si la cadena decodificada contiene caracteres sospechosos
        if (containsSuspiciousCharacters(decodedBytes)) {
            throw new IllegalArgumentException("La cadena de datos es sospechosa.");
        }

        // Crear un ByteArrayInputStream y un ObjectInputStream para deserializar
        try (ByteArrayInputStream bais = new ByteArrayInputStream(decodedBytes);
