public static void loadConfig(String yamlString) {
        Yaml yaml = new Yaml(new Constructor());
        try {
            Object config = yaml.load(yamlString);
            // Xử lý cấu hình
            handleConfig(config);
        } catch (Exception e) {
            System.err.println("Error loading configuration: " + e.getMessage());
        }
    }

    private static void handleConfig(Object config) {
        // Xử lý cấu hình dựa trên loại đối tượng
        if (config instanceof Map<?,?>) {
            // Xử lý cấu hình dạng Map
            Map<String, Object> mapConfig = (Map<String, Object>) config;
            // Duyệt qua các cặp key-value
            for (Map.Entry<String, Object> entry : mapConfig.entrySet()) {
                String key = entry.getKey();
                Object value = entry.getValue();
                // Xử lý từng cặp key-value
                processKeyValue(key, value);
            }
        } else {
            System.err.println("Unsupported configuration type: " + config.getClass().getName());
        }
    }

    private static void processKeyValue(String key, Object value) {
        // Xử lý từng cặp key-value cụ thể
        if (key.equals("database")) {
            if (value instanceof Map<?,?>) {
                Map<String, Object> dbConfig = (Map<String, Object>) value;
                String host = (String) dbConfig.get("host");
                int port = (int) dbConfig.get("port");
                String username = (String) dbConfig.get("username");
                String password = (String) dbConfig.get("password");
                // Thực hiện xử lý cấu hình database
                System.out.println("Database configuration: Host=" + host + ", Port=" + port + ", Username=" + username);
            }
        } else if (key.equals("logging")) {
            if (value instanceof Map<?,?>) {
                Map<String, Object> logConfig = (Map<String, Object>) value;
                String level = (String) logConfig.get("level");
                String file = (String) logConfig.get("file");
                // Thực hiện xử lý cấu hình logging
                System.out.println("Logging configuration: Level=" + level + ", File=" + file);
            }
        }
        // Thêm các trường khác cần xử lý theo yêu cầu
    }
}
