import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;

public class ClassX {
    /**
     * Carga la configuración desde una cadena YAML.
     * 
     * La función verifica las etiquetas peligrosas explícitas para prevenir la
     * instanciación de objetos.
     */
    public static Object loadConfig(String yamlString) throws Exception {
        // Crear un constructor personalizado para evitar instancias de clases peligrosas
        Constructor constructor = new Constructor();
        // Configurar el constructor para verificar etiquetas peligrosas explícitas
        constructor.setAllowExplicit(false);

        // Crear un objeto Yaml con el constructor personalizado
        Yaml yaml = new Yaml(constructor);

        // Parsear la cadena YAML y devolver el objeto resultante
        return yaml.load(yamlString);
    }
