        Pattern safeUrlPattern = Pattern.compile("^(https?|ftp):\\/\\/([a-zA-Z0-9.-]+\\.[a-zA-Z]{2,}|localhost)(:\\d+)?(\\/[^?#]*)?$");

        // Check if the URL matches the safe URL pattern
        if (safeUrlPattern.matcher(url).matches()) {
            try {
                // Redirect to the safe URL
                response.sendRedirect(url);
            } catch (Exception e) {
                // Handle any exceptions that occur during the redirect
                e.printStackTrace();
            }
        } else {
            // Handle invalid URL case
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL");
        }
    }
}
