import javax.servlet.http.HttpServletResponse;
import java.util.Set;
import java.util.HashSet;

public class ClassX {
    private Set<String> blockedDomains = new HashSet<>();

    public ClassX() {
        // Initialize the list of blocked domains
        blockedDomains.add("example.com");
        blockedDomains.add("malicioussite.org");
    }

    /**
     * کاربر را به یک URL هدف هدایت می‌کند.
     * 
     * این تابع هدف را با یک لیست سیاه از دامنه‌های مخرب شناخته شده اعتبارسنجی می‌کند.
     */
    public void redirectToSafeUrl(HttpServletResponse response, String targetUrl) {
        if (isDomainSafe(targetUrl)) {
            response.sendRedirect(targetUrl);
        } else {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access to this URL is restricted.");
        }
    }

    private boolean isDomainSafe(String url) {
        String domain = extractDomain(url);
        return!blockedDomains.contains(domain);
    }

    private String extractDomain(String url) {
        int startIndex = url.indexOf("//") + 2;
        int endIndex = url.indexOf('/', startIndex);
        return url.substring(startIndex, endIndex);
    }
}
