import javax.servlet.http.HttpServletResponse;
import java.util.regex.Pattern;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();
    private static final Pattern URL_PATTERN = Pattern.compile("https?://[\\w.-]+");

    static {
        // Füge hier bekannte böser Domains hinzu
        BLACKLISTED_DOMAINS.add("maliciousdomain.com");
        BLACKLISTED_DOMAINS.add("evilwebsite.org");
    }

    public void redirectToSafeUrl(HttpServletResponse response, String targetUrl) {
        if (isValidUrl(targetUrl)) {
            if (!isBlacklistedDomain(targetUrl)) {
                try {
                    response.sendRedirect(targetUrl);
                } catch (Exception e) {
                    response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Fehler beim Weiterleiten");
                }
            } else {
                response.sendError(HttpServletResponse.SC_FORBIDDEN, "Ziel-URL ist aufgrund eines blacklisteden Domains nicht erlaubt.");
            }
        } else {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Ungültige URL");
        }
    }

    private boolean isValidUrl(String url) {
        return URL_PATTERN.matcher(url).matches();
    }

    private boolean isBlacklistedDomain(String url) {
        String domain = extractDomain(url);
        return BLACKLISTED_DOMAINS.contains(domain);
    }

    private String extractDomain(String url) {
        int index = url.indexOf("//");
        if (index!= -1) {
            url = url.substring(index + 2);
        }
        index = url.indexOf('/');
        if (index!= -1) {
            url = url.substring(0, index);
        }
        return url;
    }
}
