            if (domain.equals(blacklistedDomain)) {
                return true;
            }
        }
        return false;
    }

    private String extractDomain(String url) {
        // Utilizza una libreria come Apache Commons Lang per estrarre il dominio
        // Per semplicità, si assume che l'URL sia in formato standard
        int atIndex = url.indexOf("://") + 3;
        int slashIndex = url.indexOf("/", atIndex);
        return url.substring(atIndex, slashIndex);
