    public void redirectToUrl(HttpServletResponse response, String url) {
        // Array met bekende kwaadaardige domeinen
        String[] blockedDomains = {"malware.com", "phishing.org", "suspicious.net"};

        // Controleer of het doel-URL een veilig domein is
        boolean isValidDomain = true;
        for (String domain : blockedDomains) {
            if (url.contains(domain)) {
                isValidDomain = false;
                break;
            }
        }

        // Als het domein veilig is, stuur de gebruiker door naar het doel-URL
        if (isValidDomain) {
            try {
                response.sendRedirect(url);
            } catch (Exception e) {
                // Log de fout
                System.err.println("Error redirecting to URL: " + e.getMessage());
            }
        } else {
            // Stuur de gebruiker naar een veilige fallback-URL
            try {
                response.sendRedirect("/safe-page");
            } catch (Exception e) {
                // Log de fout
                System.err.println("Error redirecting to safe page: " + e.getMessage());
            }
        }
    }
}
