import javax.servlet.http.HttpServletResponse;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("maliciousdomain.com");
        BLACKLISTED_DOMAINS.add("evil.org");
        // Agrega más dominios negados según sea necesario
    }

    /**
     * Redirige al usuario a una URL de destino.
     * 
     * La función valida el destino contra una lista negra de dominios maliciosos conocidos.
     * 
     * @param response HttpServletResponse para redirigir
     * @param destinationURL URL de destino a la que se redirigirá el usuario
     * @throws IllegalArgumentException si la URL de destino está en la lista negra
     */
    public void redirectToSafeUrl(HttpServletResponse response, String destinationURL) throws IllegalArgumentException {
        if (destinationURL == null || destinationURL.isEmpty()) {
            throw new IllegalArgumentException("La URL de destino no puede ser nula o vacía.");
        }

        String[] parts = destinationURL.split("//");
        if (parts.length < 2) {
            throw new IllegalArgumentException("La URL de destino debe tener un esquema (por ejemplo, http://).");
        }

        String domain = parts[1].split("/")[0];
        if (BLACKLISTED_DOMAINS.contains(domain)) {
            throw new IllegalArgumentException("La URL de destino contiene un dominio prohibido: " + domain);
        }

        response.sendRedirect(destinationURL);
    }
}
