import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>(Arrays.asList(
        "maliciousdomain1.com",
        "maliciousdomain2.com",
        // Adicione mais domínios aqui
    ));

    /**
     * Redireciona o usuário para uma URL de destino.
     * 
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     */
    public void redirectToSafeUrl(HttpServletResponse response, String destinationUrl) {
        if (destinationUrl == null || destinationUrl.isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL");
            return;
        }

        String domain = extractDomain(destinationUrl);

        if (BLACKLISTED_DOMAINS.contains(domain)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied to the destination URL");
            return;
        }

        try {
            response.sendRedirect(destinationUrl);
        } catch (Exception e) {
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Failed to redirect to the destination URL");
        }
    }

    private String extractDomain(String url) {
        int index = url.indexOf("//");
        if (index!= -1) {
            url = url.substring(index + 2);
        }
        index = url.indexOf('/');
        if (index!= -1) {
            url = url.substring(0, index);
        }
        return url;
    }
}
