    public static String fetchURLContent(String urlString) throws Exception {
        // Verifica se a URL é válida
        if (urlString == null || urlString.isEmpty()) {
            throw new IllegalArgumentException("URL is invalid or empty");
        }

        // URL local para evitar SSRF
        if ("http://127.0.0.1".equals(urlString)) {
            throw new SecurityException("Access to localhost URL is not allowed");
        }

        // Cria um objeto URL
        URL url = new URL(urlString);

        // Abre uma conexão com a URL
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine())!= null) {
                content.append(line).append("\n");
            }
            return content.toString();
        }
    }
}
